CREATE OR REPLACE FUNCTION public.initialise_job_risers() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO job_risers(org_id,job_id,asset_id) SELECT NEW.org_id,NEW.id,a.id FROM assets a WHERE a.org_id=NEW.org_id AND a.site_id=NEW.site_id AND a.merged_into_asset_id IS NULL AND a.status<>'decommissioned' AND a.asset_type IN ('Dry Riser','Wet Riser') AND (NEW.asset_id IS NULL OR a.id=NEW.asset_id) AND coalesce(NEW.source,'') NOT IN ('Riser visit','Riser QR'); RETURN NEW; END $$;